import os
import datetime
import hashlib
from taf.ul.teb import teb  # type: ignore
from taf.ul.sc.util import util  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.messenger import send_email_to_tester


class PostProcess(object):
    def __init__(self, source_dir, test_case_name, build, release, test_line_name, tester_username, permalink,
                 teb_url=None, base_logstore_path=None, base_logstore_url=None):
        """

        :param source_dir: folder with test logs
        :param test_case_name: tes case name - needed for package name
        :param build: e/gNB build - needed for cretae proper logstore path
        :param release: e/gNB release - needed for cretae proper logstore path
        :param test_line_name: test line on which test case was executed
        :param tester_username: tester who run test
        :param permalink: unique database id
        :param teb_url: base link to database, eg: http://teb-4g-fzm-pet.vir.krk-lab.nsn-rdnet.net
        :param base_logstore_path: base logstore path, eg: /scpet-logs/TEST/5G/
        :param base_logstore_url: base logstore url, eg: http://krk-nas.krk-lab.nsn-rdnet.net/scpet-logs/TEST/5G/
        """
        self.source_dir = source_dir
        self.test_case_name = test_case_name
        self.build = build
        self.release = release
        self.test_line_name = test_line_name
        self.tester_username = tester_username
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
        self.logstore_server = UnixFunctionality(device_name="LOGSTORE_SERVER", autoconnect=True)
        self.teb_url = teb_url
        self.base_logstore_path = base_logstore_path
        self.base_logstore_url = base_logstore_url

        self.permalink = permalink if permalink else self.generate_database_permalink(test_line_name=test_line_name)
        self.post_dir_name = '.'  # post_dir_name is source_dir until post_dir is created
        self.post_dir_path = source_dir
        self.logs_package_name = self._build_logs_package_name()
        self.logstore_destination_path = self._build_logstore_destination_path()
        self.url_logs_link = self._build_url_logs_link()

    def make_post_directory(self):
        self.post_dir_name = self._build_post_dir_name()
        self.post_dir_path = self._build_post_dir_path()
        self.unix_local.make_directory(path=self.post_dir_path)

    def remove_post_directory(self):
        self.unix_local.remove_file(path=self.post_dir_path, directory=True)

    def move_logs_to_post_directory(self, omit_robot_files=False, omit_previous_tests=True):
        files_to_omit = self.post_dir_name
        if omit_robot_files:
            files_to_omit = "{}|output*.xml|debug*.log|log*.html".format(files_to_omit)
        if omit_previous_tests:
            files_to_omit = "{}|[0-9]*_*".format(files_to_omit)
        source_files = "{}!({})".format(os.path.join(self.source_dir, ''), files_to_omit)

        self.unix_local.move(source=source_files, destination=self.post_dir_path)

        debug_log_path = os.path.join(self.source_dir, 'debug.log')
        self.unix_local.copy_file(source=debug_log_path, destination=self.post_dir_path)

    def send_result_to_database(self, data):
        teb_response = teb().upload_data_to_teb(data=data,
                                                database_url=self.teb_url,
                                                file_directory=self.post_dir_path)
        return teb_response['id']

    def create_logs_package(self):
        self.unix_local.change_directory(path=self.source_dir)

        self.unix_local.zip(zip_file=self.logs_package_name, source_files=self.post_dir_name)

    def send_package_to_logstore(self):
        self.logstore_server.make_directory(path=self.logstore_destination_path)
        util().upload_files(local_dir=self.source_dir, local_file=self.logs_package_name,
                            remote_device_name=self.logstore_server.device.name,
                            remote_dir=self.logstore_destination_path,
                            remove_source_file=True)

    def send_mail_with_test_results(self, test_execution_id, test_status, validation_link=None):
        subject = "[TAF 5G] New test results available"
        receivers = self.tester_username if isinstance(self.tester_username, list) else [self.tester_username]
        teb_link = self._build_teb_execution_link(execution_id=test_execution_id)
        msg = """<br>Test ID: {}
                 <br>Test status: {}
                 <br>Logs URL: <a href="{}">LOGS_LINK</a>
                 <br>TEB Link: <a href="{}">TEB_LINK</a>
                 <br>Validation Link: <a href="{}">VALIDATION_LINK</a>""". \
            format(test_execution_id, test_status, self.url_logs_link, teb_link, validation_link)
        send_email_to_tester(subject=subject, user_message=msg, receivers=receivers, generate_default_body=True)

    @staticmethod
    def generate_database_permalink(test_line_name, execution_date=None):
        if not execution_date:
            execution_date = datetime.datetime.now()
        unical_string = "{}{}".format(execution_date, test_line_name)

        hexdigest = hashlib.md5(unical_string.encode('utf-8')).hexdigest()
        permalink = str(int(hexdigest, 16))

        return permalink[:12]

    def _build_post_dir_path(self):
        return os.path.join(self.source_dir, self.post_dir_name)

    def _build_post_dir_name(self):
        logs_dir_name = "{}_{}".format(self.permalink, self.test_case_name)

        return logs_dir_name

    def _build_logs_package_name(self):
        logs_package_name = "{}.zip".format(self._build_post_dir_name())

        return logs_package_name

    def _build_logstore_destination_path(self):
        return os.path.join(self.base_logstore_path, self.release, self.build, self.test_case_name)

    def _build_teb_execution_link(self, execution_id):
        execution_link = "{}/search_results?execution_ids={}" \
                         "&valid+run=1&column_sets=21&table=normal&output=normal&devices=2".format(self.teb_url,
                                                                                                   execution_id)
        return execution_link

    def _build_url_logs_link(self):
        url_logs_link = "{}{}/{}/{}/{}".format(self.base_logstore_url, self.release, self.build,
                                               self.test_case_name, self.logs_package_name)
        return url_logs_link
